import {firmApiUrl, getAccessToken} from '../../api/config';
import {SupplyDocumentKind, SupplySummary, SupplyView} from './supplyModels';

async function request(path: string, init: RequestInit = {}): Promise<Response> {
    const headers = new Headers(init.headers); const token = getAccessToken();
    if (token) headers.set('Authorization', `Bearer ${token}`);
    let response: Response;
    try {response = await fetch(firmApiUrl(`supplies${path}`), {...init, headers, cache: 'no-store'});}
    catch (error) {if (error instanceof Error && error.name === 'AbortError') throw error; throw new Error('Связь с сервером потеряна. Обновите поставку и проверьте результат перед повтором операции.');}
    if (!response.ok) {
        if (response.status === 401) window.dispatchEvent(new Event('vivotech:unauthorized'));
        const body = await response.json().catch(() => ({}));
        throw new Error(typeof body.detail === 'string' ? body.detail : typeof body.message === 'string' ? body.message : 'Не удалось выполнить действие. Обновите поставку и проверьте данные.');
    }
    return response;
}
export const suppliesApi = {
    list: async (signal?: AbortSignal, search = ''): Promise<SupplySummary[]> => (await request(search ? `?search=${encodeURIComponent(search)}` : '', {signal})).json(),
    get: async (id: string, signal?: AbortSignal): Promise<SupplyView> => (await request(`/${encodeURIComponent(id)}`, {signal})).json(),
    create: async (body: {id: string; title: string; supplierName: string; categoryId: number}): Promise<SupplyView> => (await request('', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body)})).json(),
    action: async (id: string, action: string, version: string, body: object = {}, method = 'POST'): Promise<SupplyView> => (await request(`/${encodeURIComponent(id)}/${action}`, {method, headers: {'Content-Type': 'application/json'}, body: JSON.stringify({version, ...body})})).json(),
    upload: async (id: string, version: string, fileId: string, kind: SupplyDocumentKind, file: File): Promise<SupplyView> => {
        const body = new FormData(); body.append('version', version); body.append('fileId', fileId); body.append('kind', kind); body.append('file', file);
        return (await request(`/${encodeURIComponent(id)}/documents`, {method: 'POST', body})).json();
    },
    download: async (id: string, fileId: string): Promise<Blob> => (await request(`/${encodeURIComponent(id)}/documents/${encodeURIComponent(fileId)}`)).blob(),
};
export async function downloadSupplyDocument(id: string, fileId: string, name: string) {
    const blob = await suppliesApi.download(id, fileId); const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a'); anchor.href = url; anchor.download = name; document.body.appendChild(anchor); anchor.click(); anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 30000);
}
