import React, {useEffect, useState} from 'react';
import {Alert, Button, Chip, Dialog, DialogActions, DialogContent, DialogTitle, LinearProgress, MenuItem, Stack, TextField, Typography} from '@mui/material';
import {Link, useNavigate} from 'react-router-dom';
import {MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup, Surface} from '../../ui/commonStyled/commonStyled';
import {CategoryType} from '../../models/category';
import {useGetLastLevelCategoriesQuery} from '../categories/categoriesApi';
import {newRequestId} from '../warehouse/receiptDraft';
import {suppliesApi} from './suppliesApi';
import {SupplySummary, supplySteps} from './supplyModels';

export default function SuppliesPage({basePath = '/supplies'}: {basePath?: string}) {
    const navigate = useNavigate(); const categories = useGetLastLevelCategoriesQuery({type: CategoryType.Product});
    const [items, setItems] = useState<SupplySummary[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
    const [create, setCreate] = useState(false); const [busy, setBusy] = useState(false);
    const [query, setQuery] = useState('');
    const [id, setId] = useState(newRequestId); const [title, setTitle] = useState(''); const [supplier, setSupplier] = useState(''); const [category, setCategory] = useState('');
    const load = async () => {setLoading(true); setError(''); try {setItems(await suppliesApi.list(undefined, query));} catch (failure) {setError((failure as Error).message);} finally {setLoading(false);}};
    useEffect(() => {const controller = new AbortController(); suppliesApi.list(controller.signal).then(setItems).catch((failure: Error) => {if (!controller.signal.aborted) setError(failure.message);}).finally(() => {if (!controller.signal.aborted) setLoading(false);}); return () => controller.abort();}, []);
    const save = async () => {setBusy(true); setError(''); try {const result = await suppliesApi.create({id, title, supplierName: supplier, categoryId: Number(category)}); navigate(`${basePath}/${result.supply.id}`);} catch (failure) {setError((failure as Error).message);} finally {setBusy(false);}};
    return <MainDiv><Stack spacing={2}>
        <PageHeader><PageTitleGroup><PageTitle>{basePath.startsWith('/costing') ? 'Закупки поставщиков: инвойсы и оплаты' : 'Поставки'}</PageTitle><PageSubtitle>КП поставщика, регистрация товаров, закупка, оплата, документы отгрузки и приход в одной карточке.</PageSubtitle></PageTitleGroup>
            <Button variant="contained" onClick={() => {setId(newRequestId()); setCreate(true);}}>Новая поставка</Button></PageHeader>
        <Stack direction="row" gap={1}><Button disabled={loading} onClick={() => void load()}>Обновить список</Button><Button component={Link} to="/catalogGeneration/lifecycle">Порядок прохождения маршрута</Button></Stack>
        <BoxSearch query={query} setQuery={setQuery} loading={loading} onSearch={() => void load()}/>
        {items.length >= 200 && <Typography variant="body2" color="text.secondary">Показаны 200 последних совпадений. Уточните поиск по названию, поставщику или номеру карточки.</Typography>}
        {loading && <LinearProgress/>}{error && <Alert severity="error">{error}</Alert>}
        {!loading && !items.length && <Alert severity="info">Создайте поставку, укажите поставщика и загрузите его КП. CRM сохранит данные и состояние каждого этапа.</Alert>}
        {items.map(item => <Surface key={item.id}><Stack direction={{xs: 'column', sm: 'row'}} gap={2} justifyContent="space-between" alignItems={{sm: 'center'}}>
            <Stack spacing={0.5}><Typography variant="h6">{item.title}</Typography><Typography>{item.supplierName}</Typography>
                <Typography variant="body2" color="text.secondary">Обновлено: {new Date(item.updatedAt).toLocaleString('ru-RU')}</Typography></Stack>
            <Stack gap={1} alignItems="flex-start"><Chip color={item.completed ? 'success' : 'primary'} label={item.completed ? 'Оприходовано' : `${item.step} / 10 · ${supplySteps[item.step - 1]}`}/>
                <Button component={Link} to={`${basePath}/${item.id}`} variant="outlined">Открыть поставку</Button></Stack>
        </Stack></Surface>)}
        <Dialog open={create} onClose={() => {if (!busy) setCreate(false);}} fullWidth maxWidth="sm"><DialogTitle>Новая поставка</DialogTitle><DialogContent dividers><Stack spacing={2}>
            <TextField label="Название поставки" required value={title} disabled={busy} inputProps={{maxLength: 200}} onChange={e => setTitle(e.target.value)}/>
            <TextField label="Поставщик" required value={supplier} disabled={busy} inputProps={{maxLength: 300}} onChange={e => setSupplier(e.target.value)}/>
            <TextField select label="Категория товаров" required value={category} disabled={busy || categories.isLoading} onChange={e => setCategory(e.target.value)}>{(categories.data || []).map(c => <MenuItem key={c.id} value={c.id}>{c.name}</MenuItem>)}</TextField>
            {categories.isError && <Alert severity="error">Не удалось загрузить категории. <Button onClick={() => void categories.refetch()}>Повторить</Button></Alert>}
            {error && <Alert severity="error">{error}</Alert>}
        </Stack></DialogContent><DialogActions><Button disabled={busy} onClick={() => setCreate(false)}>Отмена</Button><Button variant="contained" disabled={busy || !title.trim() || !supplier.trim() || !category} onClick={() => void save()}>Создать поставку</Button></DialogActions></Dialog>
    </Stack></MainDiv>;
}

function BoxSearch({query, setQuery, loading, onSearch}: {query: string; setQuery: (query: string) => void; loading: boolean; onSearch: () => void}) {
    return <Stack direction={{xs: 'column', sm: 'row'}} spacing={1} component="form" onSubmit={event => {event.preventDefault(); onSearch();}}><TextField label="Поиск по названию, поставщику или ID" value={query} inputProps={{maxLength: 200}} onChange={e => setQuery(e.target.value)} fullWidth/><Button type="submit" disabled={loading}>Найти поставку</Button></Stack>;
}
